/**
 * Lossless, immutable source evidence for the 65 selected direct MIR4 skills.
 *
 * Every SKILL.json and direct SKILL_ATTACK.json key remains raw. Entries follow
 * class catalog order, action order, and each SKILL.AttackLink order. This module
 * is evidence-only and is not consumed by the action scheduler or runtime barrels.
 */

import {
  deepFreezeMir4NativeEvidence,
  type Mir4NativeRawSkillAttackRecord,
  type Mir4NativeRawSkillRecord,
} from './native_skill_raw_records';

export interface Mir4NativeDirectRawSkillEvidence {
  readonly rawSkillRecord: Mir4NativeRawSkillRecord;
  readonly rawAttackRecords: readonly Mir4NativeRawSkillAttackRecord[];
}

