export const MIR4_NATIVE_DIRECT_RAW_SKILL_RECORDS = Object.freeze(
  MIR4_NATIVE_DIRECT_RAW_EVIDENCE.map((entry) => entry.rawSkillRecord),
);

export const MIR4_NATIVE_DIRECT_RAW_ATTACK_RECORDS = Object.freeze(
  MIR4_NATIVE_DIRECT_RAW_EVIDENCE.flatMap((entry) => entry.rawAttackRecords),
);

const DIRECT_RAW_EVIDENCE_BY_SKILL_ID = new Map(
  MIR4_NATIVE_DIRECT_RAW_EVIDENCE.map((entry) => [entry.rawSkillRecord.SkillId, entry]),
);

export function mir4NativeDirectRawEvidenceBySkillId(
  skillId: number,
): Mir4NativeDirectRawSkillEvidence | null {
  return DIRECT_RAW_EVIDENCE_BY_SKILL_ID.get(skillId) ?? null;
}
